INSERT INTO trials (trial_id, nct_id, brief_title, official_title, overall_status, study_type, phase, enrollment_count, start_date, primary_completion_date, completion_date, brief_summary, is_fda_regulated_drug, is_fda_regulated_device, eligibility_criteria, min_age, max_age, sex, lead_sponsor_id) VALUES
(1, 'NCT04158921', 'Control:Diabetes Pilot Study I', 'Control:Diabetes - a Mobile App to Improve Glycemic Control in Patients With Diabetes', 'TERMINATED', 'INTERVENTIONAL', 'NA', 55, '2019-11-07', '2022-07-20', '2022-07-20', 'This is a single arm open label pilot clinical trial that will assess patient-reported blood glucose levels before and after using the Control:Diabetes mobile app, while collecting user feedback and recommendations for further improvements to the app functionality and user interface. This study will enroll approximately 70 individuals with insulin-treated diabetes mellitus. The study will include two online surveys (baseline and exit), one study initiation phone call, and will also collect data entered by the users into the mobile app.', 0, 0, 'Inclusion Criteria:
INSERT INTO trials (trial_id, nct_id, brief_title, official_title, overall_status, study_type, phase, enrollment_count, start_date, primary_completion_date, completion_date, brief_summary, is_fda_regulated_drug, is_fda_regulated_device, eligibility_criteria, min_age, max_age, sex, lead_sponsor_id) VALUES
(21, 'NCT04538352', 'Transition From Basal/Bolus to Once-weekly Subcutaneous Semaglutide and Basal Insulin in Patients With T2D', 'Transition From Basal/Bolus to Once-weekly Subcutaneous Semaglutide and Basal Insulin in Patients With Type-2 Diabetes Mellitus (TRANSITION-T2D) A Prospective Randomized Controlled Trial', 'COMPLETED', 'INTERVENTIONAL', 'PHASE4', 60, '2021-01-18', '2023-03-31', '2023-11-01', 'This study is designed to determine whether therapy with once-weekly sc semaglutide in combination with once-daily insulin degludec will be capable of maintaining (or improving) glycemic control, when substituted for multiple daily injections of insulin (MDI), in patients with T2D with adequate glycemic control (≤ 7.5%) on MDI-based regimens (≤ 80 units of insulin per day), vs. further titration of insulin therapy in those continuing MDI. Weight loss, hypoglycemic episodes, and improvement in diabetes-treatment satisfaction will also be assessed between the two groups.', 1, 0, 'Inclusion Criteria:
INSERT INTO trials (trial_id, nct_id, brief_title, official_title, overall_status, study_type, phase, enrollment_count, start_date, primary_completion_date, completion_date, brief_summary, is_fda_regulated_drug, is_fda_regulated_device, eligibility_criteria, min_age, max_age, sex, lead_sponsor_id) VALUES
(41, 'NCT00851019', 'Dance Dance Revolution (DDR) in Type 2 Diabetes', 'Dance Dance Revolution (DDR) Exergaming in Adults With Type 2 Diabetes Mellitus', 'COMPLETED', 'INTERVENTIONAL', 'NA', 76, '2009-02-01', '2012-07-01', '2012-07-01', 'Regular physical activity is important for the treatment of type 2 diabetes, but it is often not sustained for many reasons, including lack of interest. New video games that involve physical movement ("exergames") may help in this regard. This study will compare the "exergame" "Dance Dance Revolution" (DDR) with traditional treadmill exercise on blood sugar control among sedentary, overweight or obese adults with type 2 diabetes.', 0, 0, 'Inclusion Criteria:
INSERT INTO trials (trial_id, nct_id, brief_title, official_title, overall_status, study_type, phase, enrollment_count, start_date, primary_completion_date, completion_date, brief_summary, is_fda_regulated_drug, is_fda_regulated_device, eligibility_criteria, min_age, max_age, sex, lead_sponsor_id) VALUES
(61, 'NCT00313313', 'A Study of Saxagliptin in Subjects With Type 2 Diabetes Who Have Inadequate Blood Sugar Control With Sulfonylureas', 'A Multicenter, Randomized, Double-Blind Placebo-Controlled Phase 3 Trial to Evaluate the Efficacy and Safety of Saxagliptin in Combination With Glyburide in Subjects With Type 2 Diabetes Who Have Inadequate Glycemic Control With Glyburide Alone', 'COMPLETED', 'INTERVENTIONAL', 'PHASE3', 768, '2006-04-01', '2007-09-01', '2008-09-01', 'The purpose of this trial is to understand if adding saxagliptin to a sulfonylurea is safe and works better than increasing the amount of sulfonylurea a patient takes', 0, 0, 'Inclusion Criteria:
INSERT INTO trials (trial_id, nct_id, brief_title, official_title, overall_status, study_type, phase, enrollment_count, start_date, primary_completion_date, completion_date, brief_summary, is_fda_regulated_drug, is_fda_regulated_device, eligibility_criteria, min_age, max_age, sex, lead_sponsor_id) VALUES
(81, 'NCT07215533', 'Effects of HIIT vs. TRE on Type 2 Diabetes Risk', 'Differential Effects of HIIT vs. TRE on Type 2 Diabetes Risk in Youth and Younger Adults', 'RECRUITING', 'INTERVENTIONAL', 'NA', 40, '2024-03-15', '2025-09-30', '2025-12-30', 'The primary aim of this randomized controlled trial is to examine the effects of a 4-week high-intensity interval training (HIIT) and time-restricted eating (TRE) intervention on cardiometabolic biomarkers in adolescents and young adults.', 0, 0, 'Inclusion Criteria:
INSERT INTO trials (trial_id, nct_id, brief_title, official_title, overall_status, study_type, phase, enrollment_count, start_date, primary_completion_date, completion_date, brief_summary, is_fda_regulated_drug, is_fda_regulated_device, eligibility_criteria, min_age, max_age, sex, lead_sponsor_id) VALUES
(101, 'NCT02851849', 'A Study of LGD-6972 in Patients With Type 2 Diabetes Mellitus', 'A Randomized, Double-Blind, Placebo-Controlled, Phase 2 Study of Safety and Efficacy of LGD-6972 in Patients With Type 2 Diabetes Mellitus', 'COMPLETED', 'INTERVENTIONAL', 'PHASE2', 148, '2016-09-01', '2017-06-01', '2017-06-01', 'The purpose of this study is to evaluate the change from baseline in hemoglobin A1c (HbA1c) during 12 weeks of treatment with 3 dose levels of LGD-6972 compared to placebo in subjects with Type 2 Diabetes Mellitus (T2DM)', 0, 0, 'Inclusion Criteria:
INSERT INTO trials (trial_id, nct_id, brief_title, official_title, overall_status, study_type, phase, enrollment_count, start_date, primary_completion_date, completion_date, brief_summary, is_fda_regulated_drug, is_fda_regulated_device, eligibility_criteria, min_age, max_age, sex, lead_sponsor_id) VALUES
(121, 'NCT07494084', 'Sleep Loss and Circadian Misalignment - Mechanisms of Insulin Resistance', 'Sleep Loss and Circadian Misalignment - Mechanisms of Insulin Resistance', 'NOT_YET_RECRUITING', 'INTERVENTIONAL', 'PHASE4', 24, '2026-05-01', '2029-03-01', '2029-07-01', 'The purpose of this study is to examine the impact of timed cortisol release or differently timed cortisol rhythms on insulin resistance in both men and women undergoing sleep restriction. Chronic sleep loss is highly prevalent, affecting 1 in 3 adults in the US. Chronic sleep loss causes stress which induces insulin resistance and leads to obesity and type 2 diabetes. Many factors contribute to sleep loss including shift work, environmental disturbances, sleep/circadian disorders and comorbid medical and mental health conditions. Sleep loss increases the stress hormone cortisol in the evening and decreases daytime testosterone. Examining these hormones in a controlled laboratory environment under different sleep schedules may help researchers find solutions for adults experiencing negative health consequences related to chronic sleep loss.', 1, 0, 'Inclusion Criteria:
INSERT INTO trials (trial_id, nct_id, brief_title, official_title, overall_status, study_type, phase, enrollment_count, start_date, primary_completion_date, completion_date, brief_summary, is_fda_regulated_drug, is_fda_regulated_device, eligibility_criteria, min_age, max_age, sex, lead_sponsor_id) VALUES
(141, 'NCT00261352', 'GALLANT 14 Tesaglitazar vs. Metformin and Fenofibrate', 'A 24-Week Randomised, Double-Blind, Parallel-Group, Multi-Centre, Active-Controlled (Metformin or Metformin Combined With Fenofibrate) Study to Evaluate the Lipid Metabolic Effects, Safety and Tolerability of Tesaglitazar Therapy in Patients With Type 2 Diabetes and Low HDL-Cholesterol on a Fixed Background Therapy With a Statin', 'TERMINATED', 'INTERVENTIONAL', 'PHASE3', 1000, '2005-03-01', NULL, '2006-12-01', 'This is a 24-week study to determine the lipid metabolic effects, safety, and tolerability of tesaglitazar compared with metformin and metformin in combination with fenofibrate in patients with type 2 diabetes and low high-density lipoprotein cholesterol (HDL-C). Improvement in dyslipidemia will be evaluated. The study comprises a 2-week enrollment period, 6-week run-in and a 24-week randomized, double blind, parallel group, multi-center, active controlled (metformin with or without fenofibrate) treatment period and a 3-week follow-up. From visit 2 (run-in), all patients will receive a standardized dose of statin (rosuvastatin)', 0, 0, 'Inclusion Criteria:
INSERT INTO trials (trial_id, nct_id, brief_title, official_title, overall_status, study_type, phase, enrollment_count, start_date, primary_completion_date, completion_date, brief_summary, is_fda_regulated_drug, is_fda_regulated_device, eligibility_criteria, min_age, max_age, sex, lead_sponsor_id) VALUES
(161, 'NCT06638099', 'Increasing CGM Use Among Patients With T2D', 'Increasing Use of Continuous Glucose Monitors Among Patients With Type 2 Diabetes', 'RECRUITING', 'INTERVENTIONAL', 'NA', 318, '2024-11-04', '2026-06-30', '2026-06-30', 'Study Overview:
INSERT INTO trials (trial_id, nct_id, brief_title, official_title, overall_status, study_type, phase, enrollment_count, start_date, primary_completion_date, completion_date, brief_summary, is_fda_regulated_drug, is_fda_regulated_device, eligibility_criteria, min_age, max_age, sex, lead_sponsor_id) VALUES
(181, 'NCT03566511', 'Use of Functional MRI to Assess Functional Hypothalamic Activation in Response to Diazoxide', 'Use of Functional MRI to Assess Functional Hypothalamic Activation in Response to Diazoxide', 'TERMINATED', 'INTERVENTIONAL', 'PHASE2', 37, '2018-06-12', '2020-08-01', '2020-08-01', 'The goal of this study is to determine whether metabolic control centers in the brain can be activated in patients with type 2 diabetes (T2D) as compared to non-diabetic individuals. This is important since people with diabetes have inappropriately high production of glucose, which could be at least in part due to impaired activation of important brain centers.', 1, 0, 'Inclusion Criteria:
INSERT INTO trials (trial_id, nct_id, brief_title, official_title, overall_status, study_type, phase, enrollment_count, start_date, primary_completion_date, completion_date, brief_summary, is_fda_regulated_drug, is_fda_regulated_device, eligibility_criteria, min_age, max_age, sex, lead_sponsor_id) VALUES
(201, 'NCT05135676', 'Time in Glucose Hospital Target', 'Time in Glucose Hospital Target (TIGHT) - A Randomized Clinical Trial to Evaluate the Use of CGM to Achieve a Mean Glucose Target of 90 to 130 mg/dL Without Hypoglycemia in Hospitalized Adults With Type 2 Diabetes', 'COMPLETED', 'INTERVENTIONAL', 'NA', 169, '2022-05-10', '2024-03-01', '2024-03-01', 'Inpatient management of glycemia in people with diabetes has been inadequately studied. Previous randomized trials of intensive insulin therapy in the hospital setting resulted in excessive hypoglycemia. Current ADA guidelines (glucose 140-180 mg/dL) are by consensus with the upper bound defined by observational data and the lower bound by safety concerns. None of the previous studies of intensive glucose management used CGM technology. Whether near normal glucose levels can be achieved without increasing hypoglycemia among hospitalized patients with diabetes with the advent of CGM technology is not known.
INSERT INTO trials (trial_id, nct_id, brief_title, official_title, overall_status, study_type, phase, enrollment_count, start_date, primary_completion_date, completion_date, brief_summary, is_fda_regulated_drug, is_fda_regulated_device, eligibility_criteria, min_age, max_age, sex, lead_sponsor_id) VALUES
(221, 'NCT01346527', 'Fat Metabolism in Pregnancy and Neonatal Heart Function in Diabetes', 'Maternal Lipid Metabolism and Neonatal Heart Function in Diabetes', 'COMPLETED', 'OBSERVATIONAL', 'N/A', 79, '2011-04-01', '2014-02-01', '2014-07-01', 'Background: The health of the next generation is likely programmed in the womb (i.e.in utero), and our understanding of how that programming happens will allow us to favorably influence the health of future generations. The focus of this proposal is to examine the effect of in utero programming on heart function in children born to women with type 2 diabetes (T2DM). Specifically, neonates born to diabetic women have abnormal heart structure and weaker heart function at birth, which may predispose them to long-term heart problems in childhood, adolescence and adulthood. At present, the reason for these heart abnormalities in children born to women with diabetes is unknown and is the focus of this proposal.
INSERT INTO trials (trial_id, nct_id, brief_title, official_title, overall_status, study_type, phase, enrollment_count, start_date, primary_completion_date, completion_date, brief_summary, is_fda_regulated_drug, is_fda_regulated_device, eligibility_criteria, min_age, max_age, sex, lead_sponsor_id) VALUES
(241, 'NCT04979130', 'Comparing Semaglutide Versus Placebo on Intestinal Barrier Function in Type 2 Diabetes Mellitus (SIB)', 'A Randomized Parallel Comparison of Semaglutide Versus Placebo on Intestinal Barrier Function in Type 2 Diabetes Mellitus (SIB)', 'COMPLETED', 'INTERVENTIONAL', 'PHASE4', 69, '2022-01-01', '2024-10-16', '2024-10-16', 'This study plans to learn more about the effect of semaglutide once weekly on intestinal permeability in individuals with type 2 diabetes.', 1, 0, 'Inclusion Criteria:
INSERT INTO trials (trial_id, nct_id, brief_title, official_title, overall_status, study_type, phase, enrollment_count, start_date, primary_completion_date, completion_date, brief_summary, is_fda_regulated_drug, is_fda_regulated_device, eligibility_criteria, min_age, max_age, sex, lead_sponsor_id) VALUES
(261, 'NCT01789957', 'Extension Study for 2993-112', 'An Open-Label Extension Study of Protocol 2993-112 to Examine the Long-Term Effect on Glucose Control (HbA1c) and Safety and Tolerability of AC2993 Given Two Times a Day to Subjects Treated With Metformin Alone', 'COMPLETED', 'INTERVENTIONAL', 'PHASE3', 225, '2002-09-01', '2004-06-01', '2004-06-01', 'This multicenter, open-label extension study of Protocol 2993-112 is designed to assess long-term glucose control as measured by HbA1c (glycosylated hemoglobin) and to evaluate long-term safety and tolerability in subjects treated with metformin who receive subcutaneously injected AC2993 (10 mcg) administered twice daily. Subjects completing Protocol 2993-112 are eligible to enroll.', 0, 0, 'All of the following criteria are to be fulfilled for inclusion of an individual in the study unless the sponsor grants an exception:
