INSERT INTO trials (trial_id, nct_id, brief_title, official_title, overall_status, study_type, phase, enrollment_count, start_date, primary_completion_date, completion_date, brief_summary, is_fda_regulated_drug, is_fda_regulated_device, eligibility_criteria, min_age, max_age, sex, lead_sponsor_id) VALUES
(401, 'NCT00025883', 'Leptin to Treat Lipodystrophy', 'Long-Term Efficacy of Leptin Replacement in Treatment of Lipodystrophy', 'COMPLETED', 'INTERVENTIONAL', 'PHASE2', 103, '2001-10-01', '2015-02-01', '2015-02-01', 'This study will evaluate the safety and effectiveness of leptin replacement therapy in patients with lipodystrophy (also called lipoatrophy). Patients have a total or partial loss of fat cells. They also lack the hormone leptin, which is produced by fat cells. The leptin deficiency usually causes high blood lipid (fat) levels and insulin resistance that may lead to diabetes. Patients may have hormone imbalances, fertility problems, large appetite, and liver disease due to fat accumulation.
